-- Teste transacional em dados sintéticos; ROLLBACK preserva integralmente a produção.
BEGIN;
DO $$
DECLARE admin uuid:=gen_random_uuid(); equipe uuid:=gen_random_uuid(); documento jsonb; roteiro jsonb; ideia jsonb; pauta jsonb; pacote jsonb; ctx jsonb; negado boolean; servico jsonb; cliente uuid:=gen_random_uuid(); d1 jsonb; d2 jsonb;
BEGIN
 INSERT INTO auth.users(id,aud,role,email,raw_user_meta_data) VALUES(admin,'authenticated','authenticated','mkt-test-admin-'||admin||'@example.invalid','{"nome":"Teste Marketing Direção"}'),(equipe,'authenticated','authenticated','mkt-test-equipe-'||equipe||'@example.invalid','{"nome":"Teste Marketing Equipe"}');
 UPDATE public.profiles SET ativo=true,tipo_portal='interno' WHERE id IN (admin,equipe);
 DELETE FROM public.user_roles WHERE user_id IN (admin,equipe);
 INSERT INTO public.user_roles(user_id,role) VALUES(admin,'gestor');
 PERFORM set_config('request.jwt.claim.sub',admin::text,true);
 PERFORM public.mkt_operar('permissao',jsonb_build_object('user_id',equipe,'visualizar',true,'criar',true,'editar',true,'exportar',true));
 PERFORM set_config('request.jwt.claim.sub',equipe::text,true);
 ctx:=public.mkt_contexto();
 IF (ctx->'permissoes'->>'comercial')::boolean OR jsonb_array_length(ctx->'clientes')<>0 OR jsonb_array_length(ctx->'contratos')<>0 THEN RAISE EXCEPTION 'TESTE: contexto expôs dados comerciais'; END IF;
 IF public.has_permission(equipe,'marketing','visualizar') THEN RAISE EXCEPTION 'TESTE: acesso de conteúdo liberou CRM'; END IF;
 documento:=public.mkt_operar('salvar',jsonb_build_object('tipo','conteudo','titulo','Teste: post','dados',jsonb_build_object('checklist',jsonb_build_object('informacoes',true,'sem_promessas',true,'linguagem',true,'privacidade',true,'referencias',true,'autoria',true,'cta',true))));
 negado:=false; BEGIN PERFORM public.mkt_operar('publicar',jsonb_build_object('id',documento->>'id','link_publicacao','https://example.invalid/post','publicado_em',now())); EXCEPTION WHEN OTHERS THEN negado:=true; END;
 IF NOT negado THEN RAISE EXCEPTION 'TESTE: publicação sem aprovação foi aceita'; END IF;
 PERFORM public.mkt_operar('submeter',jsonb_build_object('id',documento->>'id'));
 negado:=false; BEGIN PERFORM public.mkt_operar('decidir',jsonb_build_object('id',documento->>'id','versao',1,'resultado','aprovado')); EXCEPTION WHEN OTHERS THEN negado:=true; END;
 IF NOT negado THEN RAISE EXCEPTION 'TESTE: equipe aprovou seu próprio conteúdo'; END IF;
 PERFORM set_config('request.jwt.claim.sub',admin::text,true);
 negado:=false; BEGIN PERFORM public.mkt_operar('decidir',jsonb_build_object('id',documento->>'id','versao',1,'resultado','ajustes')); EXCEPTION WHEN OTHERS THEN negado:=true; END;
 IF NOT negado THEN RAISE EXCEPTION 'TESTE: ajustes sem justificativa'; END IF;
 PERFORM public.mkt_operar('decidir',jsonb_build_object('id',documento->>'id','versao',1,'resultado','aprovado'));
 PERFORM set_config('request.jwt.claim.sub',equipe::text,true);
 documento:=public.mkt_operar('salvar',documento||jsonb_build_object('titulo','Teste: versão alterada'));
 IF documento->>'versao_aprovada' IS NOT NULL THEN RAISE EXCEPTION 'TESTE: edição manteve aprovação'; END IF;
 negado:=false; BEGIN PERFORM public.mkt_operar('salvar',documento||jsonb_build_object('versao',1)); EXCEPTION WHEN OTHERS THEN negado:=true; END;
 IF NOT negado THEN RAISE EXCEPTION 'TESTE: escrita concorrente ignorou versão'; END IF;
 negado:=false; BEGIN PERFORM public.mkt_operar('salvar',jsonb_build_object('tipo','material','titulo','Link inválido','dados',jsonb_build_object('link_drive','https://drive.google.com.evil.invalid/x'))); EXCEPTION WHEN OTHERS THEN negado:=true; END;
 IF NOT negado THEN RAISE EXCEPTION 'TESTE: domínio falso do Drive'; END IF;
 roteiro:=public.mkt_operar('salvar',jsonb_build_object('tipo','roteiro','titulo','Teste: roteiro','dados',jsonb_build_object('checklist',jsonb_build_object('informacoes',true,'sem_promessas',true,'linguagem',true,'privacidade',true,'referencias',true,'autoria',true,'cta',true))));
 PERFORM public.mkt_operar('submeter',jsonb_build_object('id',roteiro->>'id'));
 PERFORM set_config('request.jwt.claim.sub',admin::text,true);
 roteiro:=public.mkt_operar('decidir',jsonb_build_object('id',roteiro->>'id','versao',1,'resultado','aprovado'));
 IF roteiro->>'status'<>'aguardando_gravacao' OR roteiro->>'versao_aprovada' IS NOT NULL THEN RAISE EXCEPTION 'TESTE: roteiro aprovado como vídeo final'; END IF;
 PERFORM set_config('request.jwt.claim.sub',equipe::text,true);
 negado:=false; BEGIN PERFORM public.mkt_operar('publicar',jsonb_build_object('id',roteiro->>'id','link_publicacao','https://example.invalid/video','publicado_em',now())); EXCEPTION WHEN OTHERS THEN negado:=true; END;
 IF NOT negado THEN RAISE EXCEPTION 'TESTE: roteiro permitiu publicação antes de vídeo aprovado'; END IF;
 PERFORM public.mkt_operar('status',jsonb_build_object('id',roteiro->>'id','status','gravado'));
 roteiro:=public.mkt_operar('status',jsonb_build_object('id',roteiro->>'id','status','edicao'));
 roteiro:=public.mkt_operar('salvar',roteiro||jsonb_build_object('dados',roteiro->'dados'||jsonb_build_object('link_drive','https://drive.google.com/file/d/teste','versao_arquivo','final-1')));
 PERFORM public.mkt_operar('submeter',jsonb_build_object('id',roteiro->>'id'));
 PERFORM set_config('request.jwt.claim.sub',admin::text,true);
 roteiro:=public.mkt_operar('decidir',jsonb_build_object('id',roteiro->>'id','versao',roteiro->'versao','resultado','aprovado'));
 PERFORM set_config('request.jwt.claim.sub',equipe::text,true);
 roteiro:=public.mkt_operar('publicar',jsonb_build_object('id',roteiro->>'id','link_publicacao','https://example.invalid/video','publicado_em',now()));
 IF roteiro->>'status'<>'publicado' THEN RAISE EXCEPTION 'TESTE: publicação válida falhou'; END IF;
 ideia:=public.mkt_operar('salvar','{"tipo":"ideia","titulo":"Teste: pauta origem"}'); PERFORM public.mkt_operar('submeter',jsonb_build_object('id',ideia->>'id'));
 PERFORM set_config('request.jwt.claim.sub',admin::text,true); PERFORM public.mkt_operar('decidir',jsonb_build_object('id',ideia->>'id','versao',1,'resultado','aprovado'));
 PERFORM set_config('request.jwt.claim.sub',equipe::text,true); pauta:=public.mkt_operar('converter',jsonb_build_object('id',ideia->>'id','tipo_destino','pauta')); PERFORM public.mkt_operar('submeter',jsonb_build_object('id',pauta->>'id'));
 PERFORM set_config('request.jwt.claim.sub',admin::text,true); PERFORM public.mkt_operar('decidir',jsonb_build_object('id',pauta->>'id','versao',1,'resultado','aprovado'));
 PERFORM set_config('request.jwt.claim.sub',equipe::text,true); pacote:=jsonb_build_object('chave',gen_random_uuid(),'pauta_id',pauta->>'id','materiais',jsonb_build_array(jsonb_build_object('formato','reels'),jsonb_build_object('formato','carrossel')));
 PERFORM public.mkt_operar('pacote',pacote); PERFORM public.mkt_operar('pacote',pacote);
 IF (SELECT count(*) FROM public.mkt_itens WHERE pauta_id=(pauta->>'id')::uuid)<>2 THEN RAISE EXCEPTION 'TESTE: pacote duplicou materiais'; END IF;
 negado:=false; BEGIN PERFORM public.mkt_operar('modelo_salvar','{"nome":"Teste","tipo":"artigo"}'); EXCEPTION WHEN OTHERS THEN negado:=true; END;
 IF NOT negado THEN RAISE EXCEPTION 'TESTE: equipe alterou modelo da direção'; END IF;
 PERFORM set_config('request.jwt.claim.sub',admin::text,true);
 servico:=public.mkt_operar('servico',jsonb_build_object('nome','Serviço de teste '||gen_random_uuid()));
 INSERT INTO public.clientes(id,nome,status,ativo,criado_por) VALUES(cliente,'Cliente sintético de teste','ativo',true,admin);
 d1:=public.mkt_operar('demanda',jsonb_build_object('cliente_id',cliente,'servico_id',servico->>'id','status','contratado','contratado_em',current_date));
 d2:=public.mkt_operar('demanda',jsonb_build_object('cliente_id',cliente,'servico_id',servico->>'id','status','negociacao'));
 IF (SELECT count(*) FROM public.comercial_demandas WHERE cliente_id=cliente)<>2 THEN RAISE EXCEPTION 'TESTE: múltiplos serviços não preservados'; END IF;
 PERFORM set_config('request.jwt.claim.sub',equipe::text,true);
 negado:=false; BEGIN PERFORM public.mkt_operar('demanda',jsonb_build_object('cliente_id',cliente,'servico_id',servico->>'id','status','contratado')); EXCEPTION WHEN OTHERS THEN negado:=true; END;
 IF NOT negado THEN RAISE EXCEPTION 'TESTE: equipe acessou cliente'; END IF;
 IF jsonb_array_length(public.mkt_demanda()->'servicos')<>0 THEN RAISE EXCEPTION 'TESTE: grupo pequeno exposto'; END IF;
 IF EXISTS(SELECT 1 FROM public.mkt_versoes WHERE item_id=(roteiro->>'id')::uuid AND etapa='roteiro') IS NOT TRUE OR EXISTS(SELECT 1 FROM public.mkt_decisoes WHERE item_id=(roteiro->>'id')::uuid AND etapa='material') IS NOT TRUE THEN RAISE EXCEPTION 'TESTE: histórico de duas aprovações ausente'; END IF;
 -- Recorrência gera ocorrências próprias e não duplica na segunda execução.
 PERFORM set_config('request.jwt.claim.sub',admin::text,true);
 documento:=public.mkt_operar('salvar',jsonb_build_object('tipo','rotina','titulo','Teste: rotina semanal','data_prevista',current_date-14,'responsavel_id',equipe,'dados',jsonb_build_object('frequencia','semanal')));
 PERFORM marketing_privado.rotinas(); PERFORM marketing_privado.rotinas();
 IF (SELECT count(*) FROM public.mkt_rotina_ocorrencias WHERE rotina_id=(documento->>'id')::uuid)<>3 THEN RAISE EXCEPTION 'TESTE: recorrência duplicou ou perdeu ocorrências'; END IF;
 documento:=public.mkt_operar('salvar','{"tipo":"campanha","titulo":"Teste: campanha privada"}');
 PERFORM public.mkt_operar('financeiro',jsonb_build_object('id',documento->>'id','orcamento',100,'gasto',50));
 PERFORM public.mkt_operar('permissao',jsonb_build_object('user_id',equipe,'visualizar',true,'criar',true,'editar',true,'gerenciar',true));
 PERFORM set_config('request.jwt.claim.sub',equipe::text,true);
END $$;
SET LOCAL ROLE authenticated;
DO $$ DECLARE negado boolean; BEGIN
 IF (SELECT count(*) FROM public.clientes)<>0 OR (SELECT count(*) FROM public.comercial_demandas)<>0 OR (SELECT count(*) FROM public.mkt_campanha_financeiro)<>0 THEN RAISE EXCEPTION 'TESTE: RLS expôs cliente, demanda ou valores'; END IF;
 IF EXISTS(SELECT 1 FROM public.mkt_auditoria WHERE entidade IN ('financeiro','demanda','lead')) THEN RAISE EXCEPTION 'TESTE: auditoria expôs dados privados'; END IF;
 negado:=false; BEGIN INSERT INTO public.mkt_itens(tipo,titulo,status,versao_aprovada) VALUES('conteudo','Aprovação adulterada','aprovado',1); EXCEPTION WHEN insufficient_privilege THEN negado:=true; END;
 IF NOT negado THEN RAISE EXCEPTION 'TESTE: escrita direta contornou fluxo'; END IF;
 negado:=false; BEGIN PERFORM marketing_privado.operar('salvar','{"tipo":"concorrente","titulo":"Bypass"}'); EXCEPTION WHEN insufficient_privilege THEN negado:=true; END;
 IF NOT negado THEN RAISE EXCEPTION 'TESTE: RPC privada acessível diretamente'; END IF;
 PERFORM public.mkt_contexto();
END $$;
ROLLBACK;
